<?php
require_once 'app_bootstrap.php';
require_once 'db.php';
require_once 'security.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in to view payment details.');
$bookingId=filter_input(INPUT_GET,'booking_id',FILTER_VALIDATE_INT)?:0;
try{
    $db=db_connect();
    $statement=$db->prepare('SELECT id,booking_reference,status,payment_status,destination,hotel,from_date,to_date,people,total_amount FROM bookings WHERE id=? AND user_email=?');
    if(!$statement)throw new RuntimeException('Payment details are unavailable.');
    $email=$_SESSION['user_email'];
    $statement->bind_param('is',$bookingId,$email);
    $statement->execute();
    $booking=$statement->get_result()->fetch_assoc();
    $attempts=[];
    if($booking){$history=$db->prepare('SELECT amount,method,transaction_reference,status,created_at FROM payments WHERE booking_id=? ORDER BY id DESC');$history->bind_param('i',$bookingId);$history->execute();$result=$history->get_result();while($attempt=$result->fetch_assoc())$attempts[]=$attempt;}
}catch(Throwable $error){$booking=null;$attempts=[];}
if(!$booking)redirect_with_message('my-bookings.php','That booking could not be found.');
if(!in_array($booking['status'],['confirmed','in_progress','completed'],true))redirect_with_message('my-bookings.php#booking-'.$bookingId,'Payment becomes available after your booking is confirmed.');
$pageTitle='Payment Checkout';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo e($pageTitle);?> | Travel India</title><link rel="icon" href="img/favicon.jpg?v=1"><link rel="stylesheet" href="css/portal.css?v=15"><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js" defer></script><script src="js/practice-checkout.js?v=2" defer></script></head><body class="trips-body"><?php include 'header.php';?>
<main class="portal-page payment-page"><header class="portal-heading"><div><span>Confirmed booking</span><h1>Secure checkout</h1><p>Review your payment details for this confirmed trip.</p></div><a class="portal-button" href="my-bookings.php#booking-<?php echo (int)$booking['id'];?>">Back to My Trips</a></header>
<article class="trip-card payment-card"><div class="trip-main"><div class="checkout-mode-banner"><i class="fa-solid fa-shield-halved" aria-hidden="true"></i><span><strong>Demonstration mode</strong><small>No real funds move. Do not enter real UPI or card details.</small></span></div>
<span class="reference"><?php echo e($booking['booking_reference']?:'Booking #'.$booking['id']);?></span><h2><?php echo e($booking['destination']);?></h2><div class="trip-facts"><span><b>Hotel</b><?php echo e($booking['hotel']);?></span><span><b>Travel dates</b><?php echo e(date('d M Y',strtotime($booking['from_date'])));?> to <?php echo e(date('d M Y',strtotime($booking['to_date'])));?></span><span><b>Travellers</b><?php echo (int)$booking['people'];?></span><span><b>Amount due</b><?php echo inr($booking['total_amount']);?></span><span><b>Payment status</b><?php echo e(ucfirst($booking['payment_status']));?></span></div>
<?php if($booking['payment_status']==='paid'):?><div class="checkout-result is-success"><strong>Payment recorded</strong><p>This booking is marked as paid. No funds were transferred.</p></div>
<?php elseif($booking['payment_status']==='refunded'):?><div class="checkout-result"><strong>Payment refunded</strong><p>This booking has already been refunded.</p></div>
<?php else:?><form class="checkout-form" action="payment-process.php" method="post" id="payment-form"><?php echo csrf_input();?><input type="hidden" name="booking_id" value="<?php echo (int)$booking['id'];?>"><fieldset><legend>Payment method</legend><div class="checkout-methods"><label><input type="radio" name="method" value="practice_upi" checked><span><i class="fa-solid fa-mobile-screen-button" aria-hidden="true"></i> UPI</span></label><label><input type="radio" name="method" value="practice_card"><span><i class="fa-regular fa-credit-card" aria-hidden="true"></i> Card</span></label><label><input type="radio" name="method" value="practice_netbanking"><span><i class="fa-solid fa-building-columns" aria-hidden="true"></i> Net banking</span></label></div></fieldset>
<section class="checkout-method-panel" data-method-panel="practice_upi"><div class="checkout-method-heading"><h3>Pay using UPI</h3><span>UPI</span></div><div class="checkout-upi-layout"><div><label class="checkout-field">UPI ID<input id="practice-upi-id" type="text" inputmode="email" autocomplete="off" data-checkout-field data-sensitive placeholder="name@bank" pattern="[A-Za-z0-9._-]+@[A-Za-z0-9.-]+" title="Enter a UPI ID in the format name@bank" required><small>This value stays in your browser and is not submitted.</small></label><div class="checkout-payee"><b>Payee</b><span>Travel India</span><b>Reference</b><span><?php echo e($booking['booking_reference']);?></span></div></div><div class="checkout-qr-block"><div id="practice-qr" data-qr-payload="<?php echo e('TRAVEL-INDIA-REFERENCE:'.$booking['booking_reference']);?>"></div><small>Reference QR · not payable</small></div></div></section>
<section class="checkout-method-panel" data-method-panel="practice_card" hidden><div class="checkout-method-heading"><h3>Card details</h3><span><i class="fa-solid fa-lock" aria-hidden="true"></i> Secure form</span></div><label class="checkout-field">Name on card<input id="practice-cardholder" type="text" autocomplete="off" data-checkout-field data-sensitive maxlength="80" placeholder="Name as shown on card" required></label><label class="checkout-field">Card number<input id="practice-card-number" type="text" inputmode="numeric" autocomplete="off" data-checkout-field data-sensitive maxlength="23" placeholder="1234 5678 9012 3456" pattern="[0-9 ]{12,23}" required></label><div class="checkout-card-row"><label class="checkout-field">Expiry date<input id="practice-card-expiry" type="month" autocomplete="off" data-checkout-field data-sensitive required></label><label class="checkout-field">Security code (CVV)<input id="practice-card-cvv" type="password" inputmode="numeric" autocomplete="off" data-checkout-field data-sensitive maxlength="4" pattern="[0-9]{3,4}" placeholder="3 or 4 digits" required></label></div><small class="checkout-sensitive-note">Card details are validated in this browser and are never sent or stored.</small></section>
<section class="checkout-method-panel" data-method-panel="practice_netbanking" hidden><div class="checkout-method-heading"><h3>Net banking</h3><span><i class="fa-solid fa-building-columns" aria-hidden="true"></i> Bank transfer</span></div><label class="checkout-field">Select your bank<select id="practice-bank" autocomplete="off" data-checkout-field data-sensitive required><option value="">Choose a bank</option><option>State Bank of India</option><option>HDFC Bank</option><option>ICICI Bank</option><option>Axis Bank</option><option>Other bank</option></select></label><p class="checkout-sensitive-note">No bank login or credentials are requested.</p></section>
<label class="checkout-outcome">Payment result<select name="outcome" required><option value="success">Approved</option><option value="failure">Declined</option><option value="cancel">Cancelled by customer</option></select><small>Select the response to record.</small></label><button class="portal-button checkout-submit" type="submit"><i class="fa-solid fa-lock" aria-hidden="true"></i> Continue · <?php echo inr($booking['total_amount']);?></button></form><?php endif;?>
<?php if($attempts):?><section class="checkout-attempts"><h3>Previous attempts</h3><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Method</th><th>Result</th><th>Amount</th><th>Time</th></tr></thead><tbody><?php foreach($attempts as $attempt):$displayReference=preg_replace('/^(?:DEMO|PRACTICE)-/','TI-PAY-',$attempt['transaction_reference']);$displayMethod=strtoupper(preg_replace('/^(demo_|practice_)/','',$attempt['method']));?><tr><td><?php echo e($displayReference);?></td><td><?php echo e($displayMethod);?></td><td><?php echo e(ucfirst($attempt['status']));?></td><td><?php echo inr($attempt['amount']);?></td><td><?php echo e(date('d M Y, h:i A',strtotime($attempt['created_at'])));?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
</div></article></main><?php include 'footer.php';?></body></html>